import React from 'react';

interface Props {
  status: string;
}

const StatusBadge: React.FC<Props> = ({ status }) => {
  let colorClass = "bg-gray-100 text-gray-800";
  const s = status.toLowerCase();

  if (s.includes("active") || s.includes("current")) colorClass = "bg-emerald-100 text-emerald-800 border border-emerald-200";
  else if (s.includes("pending") || s.includes("decision")) colorClass = "bg-red-100 text-red-800 animate-pulse border border-red-200";
  else if (s.includes("dev") || s.includes("platform") || s.includes("tech")) colorClass = "bg-amber-100 text-amber-800 border border-amber-200";
  else if (s.includes("funding")) colorClass = "bg-blue-100 text-blue-800 border border-blue-200";
  else if (s.includes("research") || s.includes("dialogue")) colorClass = "bg-purple-100 text-purple-800 border border-purple-200";

  return (
    <span className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${colorClass}`}>
      {status}
    </span>
  );
};

export default StatusBadge;

