import React, { useState } from 'react';
import { LayoutDashboard, Compass, Briefcase, Users, Clock, PieChart, Menu, X } from 'lucide-react';
import Dashboard from './components/views/Dashboard';
import DirectionsView from './components/views/DirectionsView';
import PortfolioView from './components/views/PortfolioView';
import PartnershipsView from './components/views/PartnershipsView';
import TimelineView from './components/views/TimelineView';
import FinancialsView from './components/views/FinancialsView';

type View = 'dashboard' | 'directions' | 'portfolio' | 'partnerships' | 'timeline' | 'financials';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'directions', label: 'Strategic Directions', icon: Compass },
    { id: 'portfolio', label: 'Project Portfolio', icon: Briefcase },
    { id: 'partnerships', label: 'Partnerships', icon: Users },
    { id: 'timeline', label: 'Timeline', icon: Clock },
    { id: 'financials', label: 'Financials', icon: PieChart },
  ] as const;

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard': return <Dashboard />;
      case 'directions': return <DirectionsView />;
      case 'portfolio': return <PortfolioView />;
      case 'partnerships': return <PartnershipsView />;
      case 'timeline': return <TimelineView />;
      case 'financials': return <FinancialsView />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex">
      {/* Mobile Menu Button */}
      <button 
        onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        className="lg:hidden fixed top-4 right-4 z-50 p-2 bg-white rounded-md shadow-md"
      >
        {isMobileMenuOpen ? <X /> : <Menu />}
      </button>

      {/* Sidebar */}
      <aside className={`
        fixed lg:static inset-y-0 left-0 z-40 w-64 bg-slate-900 text-slate-300 transform transition-transform duration-200 ease-in-out
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="p-6 border-b border-slate-800">
          <h1 className="text-xl font-bold text-white tracking-tight">FEEL AGAIN</h1>
          <p className="text-xs text-slate-500 mt-1">Deployment Matrix v1.0</p>
        </div>
        <nav className="p-4 space-y-1">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => {
                  setCurrentView(item.id as View);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors ${
                  isActive 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' 
                    : 'hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon size={18} />
                <span className="font-medium">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="absolute bottom-0 w-full p-6 border-t border-slate-800">
           <div className="flex items-center gap-2 text-xs text-slate-500">
             <div className="w-2 h-2 rounded-full bg-emerald-500"></div>
             System Status: Active
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 min-w-0 overflow-y-auto h-screen">
        <div className="p-8 max-w-7xl mx-auto">
          <header className="mb-8">
            <h2 className="text-2xl font-bold text-slate-800">
              {navItems.find(n => n.id === currentView)?.label}
            </h2>
            <p className="text-slate-500 text-sm mt-1">
               Feel Again Program / Unified Deployment Matrix / January 2026
            </p>
          </header>

          <div className="animate-fade-in">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

