import React, { useState } from 'react';
import { LayoutDashboard, Compass, Briefcase, Users, Clock, PieChart, Menu, X, Languages } from 'lucide-react';
import Dashboard from './components/views/Dashboard';
import DirectionsView from './components/views/DirectionsView';
import PortfolioView from './components/views/PortfolioView';
import PartnershipsView from './components/views/PartnershipsView';
import TimelineView from './components/views/TimelineView';
import FinancialsView from './components/views/FinancialsView';
import { Lang } from './types';

type View = 'dashboard' | 'directions' | 'portfolio' | 'partnerships' | 'timeline' | 'financials';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [lang, setLang] = useState<Lang>('en');

  const navItems = [
    { id: 'dashboard', label: { en: 'Dashboard', uk: 'Дашборд' }, icon: LayoutDashboard },
    { id: 'directions', label: { en: 'Strategic Pillars', uk: 'Стратегічні Напрями' }, icon: Compass },
    { id: 'portfolio', label: { en: 'Intervention Portfolio', uk: 'Портфель Втручань' }, icon: Briefcase },
    { id: 'partnerships', label: { en: 'Partners & Coverage', uk: 'Партнери та Охоплення' }, icon: Users },
    { id: 'timeline', label: { en: 'Roadmap', uk: 'Дорожня Карта' }, icon: Clock },
    { id: 'financials', label: { en: 'Resource Mobilization', uk: 'Мобілізація Ресурсів' }, icon: PieChart },
  ] as const;

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard': return <Dashboard lang={lang} />;
      case 'directions': return <DirectionsView lang={lang} />;
      case 'portfolio': return <PortfolioView lang={lang} />;
      case 'partnerships': return <PartnershipsView lang={lang} />;
      case 'timeline': return <TimelineView lang={lang} />;
      case 'financials': return <FinancialsView lang={lang} />;
      default: return <Dashboard lang={lang} />;
    }
  };

  const toggleLang = () => setLang(prev => prev === 'en' ? 'uk' : 'en');

  return (
    <div className="min-h-screen bg-slate-50 flex font-sans">
      {/* Mobile Menu Button */}
      <button 
        onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        className="lg:hidden fixed top-4 right-4 z-50 p-2 bg-white rounded-md shadow-md text-slate-700"
      >
        {isMobileMenuOpen ? <X /> : <Menu />}
      </button>

      {/* Sidebar */}
      <aside className={`
        fixed lg:static inset-y-0 left-0 z-40 w-72 bg-slate-900 text-slate-300 transform transition-transform duration-200 ease-in-out flex flex-col
        ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="p-6 border-b border-slate-800">
          <div className="flex justify-between items-center mb-1">
            <h1 className="text-xl font-bold text-white tracking-tight">FEEL AGAIN</h1>
            <button onClick={toggleLang} className="flex items-center gap-1 text-xs bg-slate-800 hover:bg-slate-700 px-2 py-1 rounded transition-colors text-slate-200">
              <Languages size={12} />
              {lang.toUpperCase()}
            </button>
          </div>
          <p className="text-xs text-slate-500">{lang === 'en' ? 'Unified Deployment Matrix' : 'Уніфікована Матриця Розгортання'}</p>
        </div>
        <nav className="p-4 space-y-1 flex-1">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentView === item.id;
            return (
              <button
                key={item.id}
                onClick={() => {
                  setCurrentView(item.id as View);
                  setIsMobileMenuOpen(false);
                }}
                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-all duration-200 ${
                  isActive 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' 
                    : 'hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon size={18} />
                <span className="font-medium text-sm">{item.label[lang]}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-6 border-t border-slate-800">
           <div className="flex items-center gap-2 text-xs text-slate-500">
             <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
             {lang === 'en' ? 'System Status: Operational' : 'Статус: Активно'}
           </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 min-w-0 overflow-y-auto h-screen bg-slate-50/50">
        <div className="p-8 max-w-7xl mx-auto">
          <header className="mb-8 flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
              <h2 className="text-2xl font-bold text-slate-800 tracking-tight">
                {navItems.find(n => n.id === currentView)?.label[lang]}
              </h2>
              <p className="text-slate-500 text-sm mt-1">
                 Feel Again Program / {lang === 'en' ? 'Unified Matrix' : 'Уніфікована Матриця'} / 2026
              </p>
            </div>
            <div className="text-xs font-mono text-slate-400 bg-white px-3 py-1.5 rounded border border-slate-200 shadow-sm">
                ID: FA-2026-UA
            </div>
          </header>

          <div className="animate-fade-in">
            {renderContent()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

